#!/bin/bash
# resume-picker.sh - interactive session picker for bare `claude -r` (bash and zsh)
# Called by the resume shim (resume-shim.sh) when -r/--resume is present with NO
# session id. Plain Claude Code's own picker would resume a Lumo session under a model
# it does not know ("Session model lumo-max could not be restored"), and by the time
# its picker runs it is too late to reroute. This helper lists recent transcripts first
# so the right launcher (claude-lumo vs the real claude) can be chosen.
# Do not edit this file: it belongs to the claude-lumo repo and updates overwrite it.
#
# Usage: bash resume-picker.sh <original claude args...>  (normally run by the shim)
#   - Lists the 15 most recent transcripts (by mtime) across the same stores and in
#     the same order the shim uses, showing engine (lumo/claude), last-modified time,
#     project folder basename and the short id (first 8 chars).
#   - A number resumes that session with the matching engine: the bare -r/--resume
#     flag is replaced by "--resume <full-id>" and every other argument is kept in order.
#   - "p" opens plain Claude Code's own picker (the behavior without this helper).
#     Empty or invalid input also falls through to the real claude with the ORIGINAL
#     arguments unchanged. Fail-open: the helper never traps the user. Same for
#     non-tty stdin and empty transcript stores.
#   - RESUME_PICKER_FORCE_MENU=1 forces the menu even with redirected stdin, so the
#     test harness can drive the interactive path.
#
# Transcript search order (same as resume-shim.sh):
#   1. $CLAUDE_CONFIG_DIR if set
#   2. ~/.claude (shared mode)
#   3. ~/.claude-lumo/config (the separated Lumo data store, when data separation is on)

set -u

mtime_of() { # mtime_of <file> -> epoch seconds (0 if unavailable)
    local m
    m="$(stat -c '%Y' "$1" 2>/dev/null)" || m=""
    [ -z "$m" ] && { m="$(stat -f '%m' "$1" 2>/dev/null)" || m="0"; }
    printf '%s' "$m"
}

fmt_time() { # fmt_time <epoch> -> readable local time ('?' on failure)
    date -d "@$1" '+%Y-%m-%d %H:%M' 2>/dev/null \
        || date -r "$1" '+%Y-%m-%d %H:%M' 2>/dev/null \
        || printf '?'
}

_picker_py=""
for _d in python python3 py; do
    command -v "$_d" >/dev/null 2>&1 && { _picker_py="$_d"; break; }
done
_picker_sep="$(dirname "$0")/separate_data.py"

# is_lumo_t <file>: record-level Lumo check (issues #26, #93 - a quoted "model":"lumo-
# inside tool text must not count). Substring fallback only when no python exists.
is_lumo_t() {
    if [ -n "$_picker_py" ]; then
        "$_picker_py" "$_picker_sep" is-lumo "$1"
        return $?
    fi
    grep -qF '"model":"lumo-' "$1"
}

# Non-interactive (stdin redirected): behave exactly like the old shim - plain claude,
# original args - so scripts and pipelines are never stalled on a menu.
if [ ! -t 0 ] && [ "${RESUME_PICKER_FORCE_MENU:-}" != "1" ]; then
    command claude "$@"
    exit $?
fi

# Scan the transcript stores; collect "mtime<TAB>engine<TAB>path" rows.
dirs=()
[ -n "${CLAUDE_CONFIG_DIR:-}" ] && dirs+=("$CLAUDE_CONFIG_DIR")
dirs+=("$HOME/.claude" "${CLAUDE_LUMO_STATE_DIR:-$HOME/.claude-lumo}/config")
rows=""
_nl=$'\n'
_seen=$_nl
for d in "${dirs[@]}"; do
    case "$_seen" in *"$_nl$d$_nl"*) continue;; esac   # dir dedupe (e.g. CLAUDE_CONFIG_DIR=~/.claude)
    _seen="$_seen$d$_nl"
    for t in "$d"/projects/*/*.jsonl; do
        [ -f "$t" ] || continue
        eng="claude"
        is_lumo_t "$t" && eng="lumo"
        rows+="$(mtime_of "$t")"$'\t'"$eng"$'\t'"$t"$'\n'
    done
done
latest="$(printf '%s' "$rows" | sort -rn | head -15)"

# No transcripts anywhere -> plain claude, original args.
if [ -z "$latest" ]; then
    command claude "$@"
    exit $?
fi

# Print the menu; remember path/engine per row for the lookup below.
echo "Resume which session?"
paths=""
count=0
while IFS=$'\t' read -r mt eng path; do
    [ -n "$path" ] || continue
    count=$((count + 1))
    paths+="$path"$'\t'"$eng"$'\n'
    base="$(basename "$(dirname "$path")")"
    short="$(basename "$path" .jsonl)"
    printf '%2d) [%s] %-16s %s  %s\n' "$count" "$eng" "$(fmt_time "$mt")" "$base" "${short:0:8}"
done <<< "$latest"
printf "  p) plain Claude Code's own picker\n"
printf 'Choice (number, p, or Enter for plain claude): '
read -r choice || choice=""

if [ "$choice" = "p" ]; then
    command claude "$@"
    exit $?
fi

# Find the chosen row (an invalid or out-of-range number leaves found empty).
found="" found_eng=""
case "$choice" in
    ''|*[!0-9]*) ;;
    *)
        i=0
        while IFS=$'\t' read -r p e; do
            [ -n "$p" ] || continue
            i=$((i + 1))
            if [ "$i" = "$choice" ]; then found="$p"; found_eng="$e"; fi
        done <<< "$paths"
        ;;
esac
if [ -z "$found" ]; then
    command claude "$@"   # fail-open: original arguments unchanged
    exit $?
fi

full_id="$(basename "$found" .jsonl)"

# Rebuild "$@": same arguments in order minus the bare -r/--resume token.
# Tokens after "--" are end-of-options: a literal -r/--resume there is a
# positional argument and must be kept (same end-of-options logic as the shim).
n=$#
_strip_end=0
while [ "$n" -gt 0 ]; do
    a="$1"
    shift
    if [ "$_strip_end" = "1" ]; then
        set -- "$@" "$a"
    else
        case "$a" in
            --) _strip_end=1; set -- "$@" "$a" ;;
            -r|--resume) ;;
            *) set -- "$@" "$a" ;;
        esac
    fi
    n=$((n - 1))
done

if [ "$found_eng" = "lumo" ]; then
    command claude-lumo --resume "$full_id" "$@"
    exit $?
else
    command claude --resume "$full_id" "$@"
    exit $?
fi
